<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Happy Tails Dog Walking | Trusted, Local, Loving Care</title>
  <meta name="description" content="Happy Tails Dog Walking offers reliable, insured dog walking, puppy visits, and pet sitting in your neighborhood. Book your first walk today.">
  <style>
    :root {
      --primary: #2f7d5b;
      --primary-dark: #225c43;
      --accent: #f4a340;
      --light: #f7f5ef;
      --text: #2b2b2b;
      --muted: #666;
      --radius: 12px;
    }
    * { box-sizing: border-box; margin: 0; padding: 0; }
    body {
      font-family: "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
      color: var(--text);
      line-height: 1.6;
      background: #fff;
    }
    a { color: inherit; text-decoration: none; }
    .container { width: 90%; max-width: 1100px; margin: 0 auto; }

    /* Header */
    header {
      background: #fff;
      position: sticky;
      top: 0;
      z-index: 10;
      box-shadow: 0 2px 8px rgba(0,0,0,0.06);
    }
    .nav {
      display: flex;
      align-items: center;
      justify-content: space-between;
      padding: 1rem 0;
    }
    .logo { font-size: 1.5rem; font-weight: 700; color: var(--primary); }
    .logo span { color: var(--accent); }
    nav ul { display: flex; gap: 1.5rem; list-style: none; align-items: center; }
    nav a:hover { color: var(--primary); }
    .btn {
      display: inline-block;
      background: var(--accent);
      color: #fff;
      padding: 0.75rem 1.5rem;
      border-radius: var(--radius);
      font-weight: 600;
      transition: background 0.2s;
    }
    .btn:hover { background: #e08d22; }
    .btn-outline {
      background: transparent;
      border: 2px solid #fff;
    }
    .btn-outline:hover { background: rgba(255,255,255,0.15); }

    /* Hero */
    .hero {
      background: linear-gradient(rgba(34,92,67,0.75), rgba(34,92,67,0.75)),
                  url("https://images.unsplash.com/photo-1548199973-03cce0bbc87b?auto=format&fit=crop&w=1600&q=80") center/cover;
      color: #fff;
      padding: 7rem 0;
      text-align: center;
    }
    .hero h1 { font-size: clamp(2rem, 5vw, 3.25rem); margin-bottom: 1rem; }
    .hero p { font-size: 1.2rem; max-width: 640px; margin: 0 auto 2rem; }
    .hero-buttons { display: flex; gap: 1rem; justify-content: center; flex-wrap: wrap; }

    /* Sections */
    section { padding: 5rem 0; }
    .section-title { text-align: center; margin-bottom: 3rem; }
    .section-title h2 { font-size: 2rem; color: var(--primary-dark); margin-bottom: 0.5rem; }
    .section-title p { color: var(--muted); }

    /* Trust bar */
    .trust {
      background: var(--light);
      padding: 2rem 0;
    }
    .trust-items {
      display: flex;
      justify-content: space-around;
      flex-wrap: wrap;
      gap: 1rem;
      text-align: center;
      font-weight: 600;
      color: var(--primary-dark);
    }

    /* Cards */
    .grid {
      display: grid;
      grid-template-columns: repeat(auto-fit, minmax(240px, 1fr));
      gap: 2rem;
    }
    .card {
      background: #fff;
      border-radius: var(--radius);
      padding: 2rem;
      box-shadow: 0 4px 16px rgba(0,0,0,0.07);
      text-align: center;
    }
    .card .icon { font-size: 2.5rem; margin-bottom: 1rem; }
    .card h3 { margin-bottom: 0.5rem; color: var(--primary-dark); }
    .card p { color: var(--muted); margin-bottom: 1rem; }
    .price { font-size: 1.4rem; font-weight: 700; color: var(--accent); }
    .price small { font-size: 0.9rem; color: var(--muted); font-weight: 400; }

    /* How it works */
    .steps { background: var(--light); }
    .step-num {
      width: 50px; height: 50px;
      border-radius: 50%;
      background: var(--primary);
      color: #fff;
      display: flex; align-items: center; justify-content: center;
      font-weight: 700; font-size: 1.25rem;
      margin: 0 auto 1rem;
    }

    /* About */
    .about-wrap {
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 3rem;
      align-items: center;
    }
    .about-wrap img { width: 100%; border-radius: var(--radius); }
    .about-wrap h2 { color: var(--primary-dark); margin-bottom: 1rem; font-size: 2rem; }
    .about-wrap p { margin-bottom: 1rem; color: var(--muted); }

    /* Testimonials */
    .testimonial { text-align: left; }
    .testimonial blockquote { font-style: italic; margin-bottom: 1rem; color: var(--text); }
    .testimonial cite { font-weight: 600; color: var(--primary); font-style: normal; }
    .stars { color: var(--accent); margin-bottom: 0.5rem; }

    /* CTA */
    .cta {
      background: var(--primary);
      color: #fff;
      text-align: center;
    }
    .cta h2 { font-size: 2rem; margin-bottom: 1rem; }
    .cta p { margin-bottom: 2rem; }

    /* Contact form */
    form {
      max-width: 600px;
      margin: 0 auto;
      display: grid;
      gap: 1rem;
    }
    input, select, textarea {
      width: 100%;
      padding: 0.85rem;
      border: 1px solid #ccc;
      border-radius: var(--radius);
      font: inherit;
    }
    textarea { min-height: 120px; resize: vertical; }
    button.btn { border: none; cursor: pointer; font-size: 1rem; }

    /* Footer */
    footer {
      background: #1d2b24;
      color: #cfd8d3;
      padding: 3rem 0 1.5rem;
    }
    .footer-grid {
      display: grid;
      grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
      gap: 2rem;
      margin-bottom: 2rem;
    }
    footer h4 { color: #fff; margin-bottom: 0.75rem; }
    footer ul { list-style: none; }
    footer li { margin-bottom: 0.4rem; }
    footer a:hover { color: var(--accent); }
    .copyright { text-align: center; font-size: 0.9rem; border-top: 1px solid #34453c; padding-top: 1.5rem; }

    @media (max-width: 768px) {
      nav ul li:not(:last-child) { display: none; }
      .about-wrap { grid-template-columns: 1fr; }
    }
  </style>
</head>
<body>

  <!-- Header -->
  <header>
    <div class="container nav">
      <a href="#" class="logo">Happy<span>Tails</span> 🐾</a>
      <nav>
        <ul>
          <li><a href="#services">Services</a></li>
          <li><a href="#how">How It Works</a></li>
          <li><a href="#about">About</a></li>
          <li><a href="#reviews">Reviews</a></li>
          <li><a href="#contact" class="btn">Book a Walk</a></li>
        </ul>
      </nav>
    </div>
  </header>

  <!-- Hero -->
  <section class="hero">
    <div class="container">
      <h1>Happy Dogs. Happy Owners. Every Single Walk.</h1>
      <p>Reliable, loving dog walking and pet care from a local team that treats your pup like family, rain or shine.</p>
      <div class="hero-buttons">
        <a href="#contact" class="btn">Book Your First Walk</a>
        <a href="#services" class="btn btn-outline">View Services</a>
      </div>
    </div>
  </section>

  <!-- Trust bar -->
  <div class="trust">
    <div class="container trust-items">
      <div>✅ Fully Insured &amp; Bonded</div>
      <div>🩺 Pet First Aid Certified</div>
      <div>📍 GPS-Tracked Walks</div>
      <div>📸 Photo Updates Every Visit</div>
    </div>
  </div>

  <!-- Services -->
  <section id="services">
    <div class="container">
      <div class="section-title">
        <h2>Our Services</h2>
        <p>Flexible care that fits your schedule and your dog's needs.</p>
      </div>
      <div class="grid">
        <div class="card">
          <div class="icon">🦮</div>
          <h3>Solo Walks</h3>
          <p>One-on-one attention for dogs who prefer their own company or need extra focus.</p>
          <div class="price">$25 <small>/ 30 min</small></div>
        </div>
        <div class="card">
          <div class="icon">🐕‍🦺</div>
          <h3>Group Adventures</h3>
          <p>Small groups of up to 4 friendly dogs for socialization and fun.</p>
          <div class="price">$18 <small>/ 45 min</small></div>
        </div>
        <div class="card">
          <div class="icon">🐶</div>
          <h3>Puppy Visits</h3>
          <p>Potty breaks, playtime, and feeding for young pups who can't hold it all day.</p>
          <div class="price">$20 <small>/ 20 min</small></div>
        </div>
        <div class="card">
          <div class="icon">🏡</div>
          <h3>Pet Sitting</h3>
          <p>Overnight or drop-in care while you travel, so your dog stays comfy at home.</p>
          <div class="price">$65 <small>/ night</small></div>
        </div>
      </div>
    </div>
  </section>

  <!-- How it works -->
  <section id="how" class="steps">
    <div class="container">
      <div class="section-title">
        <h2>How It Works</h2>
        <p>Getting started is easy, and your first meet &amp; greet is free.</p>
      </div>
      <div class="grid">
        <div class="card">
          <div class="step-num">1</div>
          <h3>Request a Meet &amp; Greet</h3>
          <p>Fill out our quick form and we'll schedule a free visit to meet you and your pup.</p>
        </div>
        <div class="card">
          <div class="step-num">2</div>
          <h3>Build Your Plan</h3>
          <p>We'll create a custom walking schedule based on your dog's energy, age, and routine.</p>
        </div>
        <div class="card">
          <div class="step-num">3</div>
          <h3>Relax &amp; Get Updates</h3>
          <p>Receive photos, GPS maps, and notes after every walk right on your phone.</p>
        </div>
      </div>
    </div>
  </section>

  <!-- About -->
  <section id="about">
    <div class="container about-wrap">
      <img src="https://images.unsplash.com/photo-1601758228041-f3b2795255f1?auto=format&fit=crop&w=900&q=80" alt="Dog walker with two happy dogs on a sunny trail">
      <div>
        <h2>Local Dog Lovers You Can Trust</h2>
        <p>Happy Tails started in 2018 with one walker, one leash, and a whole lot of love for dogs. Today, our small team of background-checked, certified walkers cares for hundreds of pups across the neighborhood.</p>
        <p>We believe every dog deserves exercise, enrichment, and attention, and every owner deserves peace of mind. That's why we keep our groups small, our communication clear, and our walkers consistent.</p>
        <a href="#contact" class="btn">Meet Our Team</a>
      </div>
    </div>
  </section>

  <!-- Testimonials -->
  <section id="reviews" class="steps">
    <div class="container">
      <div class="section-title">
        <h2>What Pet Parents Say</h2>
        <p>Rated 4.9/5 from over 300 happy clients.</p>
      </div>
      <div class="grid">
        <div class="card testimonial">
          <div class="stars">★★★★★</div>
          <blockquote>"Our anxious rescue, Biscuit, now gets excited when his walker arrives. The photo updates make my workday so much better!"</blockquote>
          <cite>— Sarah M.</cite>
        </div>
        <div class="card testimonial">
          <div class="stars">★★★★★</div>
          <blockquote>"Punctual, professional, and genuinely caring. I've tried three other services and Happy Tails is by far the best."</blockquote>
          <cite>— James R.</cite>
        </div>
        <div class="card testimonial">
          <div class="stars">★★★★★</div>
          <blockquote>"They handled puppy visits for our lab while we both worked. She's healthier, calmer, and totally house trained now."</blockquote>
          <cite>— Priya &amp; Dan K.</cite>
        </div>
      </div>
    </div>
  </section>

  <!-- CTA -->
  <section class="cta">
    <div class="container">
      <h2>Ready for Happier Walks?</h2>
      <p>Your first meet &amp; greet is always free. New clients get 20% off their first week!</p>
      <a href="#contact" class="btn">Claim Your Discount</a>
    </div>
  </section>

  <!-- Contact -->
  <section id="contact">
    <div class="container">
      <div class="section-title">
        <h2>Book a Free Meet &amp; Greet</h2>
        <p>Tell us about your pup and we'll get back to you within 24 hours.</p>
      </div>
      <form action="#" method="post">
        <input type="text" name="name" placeholder="Your Name" required>
        <input type="email" name="email" placeholder="Email Address" required>
        <input type="tel" name="phone" placeholder="Phone Number">
        <input type="text" name="dog" placeholder="Dog's Name &amp; Breed">
        <select name="service" required>
          <option value="">Select a Service</option>
          <option>Solo Walks</option>
          <option>Group Adventures</option>
          <option>Puppy Visits</option>
          <option>Pet Sitting</option>
        </select>
        <textarea name="message" placeholder="Anything we should know about your dog?"></textarea>
        <button type="submit" class="btn">Send Request</button>
      </form>
    </div>
  </section>

  <!-- Footer -->
  <footer>
    <div class="container">
      <div class="footer-grid">
        <div>
          <h4>Happy Tails 🐾</h4>
          <p>Trusted dog walking and pet care, serving our community since 2018.</p>
        </div>
        <div>
          <h4>Quick Links</h4>
          <ul>
            <li><a href="#services">Services</a></li>
            <li><a href="#how">How It Works</a></li>
            <li><a href="#about">About Us</a></li>
            <li><a href="#reviews">Reviews</a></li>
          </ul>
        </div>
        <div>
          <h4>Contact</h4>
          <ul>
            <li>📞 (555) 123-4567</li>
            <li>✉️ hello@happytailswalks.com</li>
            <li>🕗 Mon–Sat, 7am–7pm</li>
          </ul>
        </div>
        <div>
          <h4>Follow Us</h4>
          <ul>
            <li><a href="#">Instagram</a></li>
