<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>Inkwell: Notes that think with you</title>
  <meta name="description" content="Inkwell is the fast, private, beautifully simple note-taking app for capturing ideas, organizing your thoughts, and finding anything in seconds." />
  <style>
    :root {
      --bg: #fbfaf7;
      --surface: #ffffff;
      --ink: #1c1b19;
      --muted: #6b6860;
      --accent: #3b5bdb;
      --accent-soft: #e7ecff;
      --border: #e8e5de;
      --radius: 14px;
      --max: 1120px;
    }
    * { box-sizing: border-box; margin: 0; padding: 0; }
    body {
      font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Inter, Roboto, sans-serif;
      background: var(--bg);
      color: var(--ink);
      line-height: 1.6;
      -webkit-font-smoothing: antialiased;
    }
    a { color: inherit; text-decoration: none; }
    .container { max-width: var(--max); margin: 0 auto; padding: 0 24px; }

    /* Nav */
    nav {
      position: sticky; top: 0; z-index: 10;
      background: rgba(251, 250, 247, 0.85);
      backdrop-filter: blur(10px);
      border-bottom: 1px solid var(--border);
    }
    .nav-inner { display: flex; align-items: center; justify-content: space-between; height: 64px; }
    .logo { font-weight: 700; font-size: 1.25rem; display: flex; align-items: center; gap: 8px; }
    .logo-mark {
      width: 28px; height: 28px; border-radius: 8px;
      background: var(--accent); color: #fff;
      display: grid; place-items: center; font-size: 0.9rem;
    }
    .nav-links { display: flex; gap: 28px; align-items: center; font-size: 0.95rem; color: var(--muted); }
    .nav-links a:hover { color: var(--ink); }

    /* Buttons */
    .btn {
      display: inline-flex; align-items: center; gap: 8px;
      padding: 12px 22px; border-radius: 999px;
      font-weight: 600; font-size: 0.95rem;
      transition: transform 0.15s ease, box-shadow 0.15s ease, background 0.15s ease;
    }
    .btn-primary { background: var(--accent); color: #fff; box-shadow: 0 6px 20px rgba(59, 91, 219, 0.25); }
    .btn-primary:hover { transform: translateY(-1px); box-shadow: 0 10px 26px rgba(59, 91, 219, 0.32); }
    .btn-ghost { border: 1px solid var(--border); background: var(--surface); }
    .btn-ghost:hover { border-color: var(--ink); }
    .btn-sm { padding: 8px 16px; font-size: 0.9rem; }

    /* Hero */
    .hero { padding: 96px 0 72px; text-align: center; }
    .badge {
      display: inline-block; padding: 6px 14px; border-radius: 999px;
      background: var(--accent-soft); color: var(--accent);
      font-size: 0.85rem; font-weight: 600; margin-bottom: 24px;
    }
    .hero h1 {
      font-size: clamp(2.5rem, 6vw, 4.25rem);
      line-height: 1.08; letter-spacing: -0.03em;
      max-width: 820px; margin: 0 auto 20px;
    }
    .hero h1 em { font-style: normal; color: var(--accent); }
    .hero p { font-size: 1.2rem; color: var(--muted); max-width: 620px; margin: 0 auto 36px; }
    .hero-ctas { display: flex; gap: 12px; justify-content: center; flex-wrap: wrap; }
    .hero-note { margin-top: 16px; font-size: 0.875rem; color: var(--muted); }

    /* App preview */
    .preview {
      margin: 64px auto 0; max-width: 980px;
      background: var(--surface); border: 1px solid var(--border);
      border-radius: 18px; overflow: hidden;
      box-shadow: 0 30px 80px rgba(28, 27, 25, 0.12);
      text-align: left;
    }
    .preview-bar { display: flex; gap: 6px; padding: 14px 16px; border-bottom: 1px solid var(--border); }
    .preview-bar span { width: 11px; height: 11px; border-radius: 50%; background: #e2dfd8; }
    .preview-body { display: grid; grid-template-columns: 220px 1fr; min-height: 340px; }
    .sidebar { border-right: 1px solid var(--border); padding: 18px; font-size: 0.9rem; color: var(--muted); }
    .sidebar h4 { font-size: 0.75rem; text-transform: uppercase; letter-spacing: 0.08em; margin: 14px 0 8px; }
    .sidebar div { padding: 6px 10px; border-radius: 8px; }
    .sidebar .active { background: var(--accent-soft); color: var(--accent); font-weight: 600; }
    .editor { padding: 32px 40px; }
    .editor h3 { font-size: 1.6rem; margin-bottom: 6px; letter-spacing: -0.02em; }
    .editor .meta { font-size: 0.8rem; color: var(--muted); margin-bottom: 20px; }
    .editor p { margin-bottom: 12px; }
    .editor ul { padding-left: 20px; margin-bottom: 12px; }
    .tag { display: inline-block; background: var(--accent-soft); color: var(--accent); padding: 1px 8px; border-radius: 6px; font-size: 0.85rem; }
    .link { color: var(--accent); border-bottom: 1px dashed var(--accent); }

    /* Logos */
    .trust { padding: 48px 0; text-align: center; color: var(--muted); font-size: 0.9rem; }
    .trust-logos { display: flex; justify-content: center; gap: 48px; flex-wrap: wrap; margin-top: 18px; font-weight: 700; font-size: 1.1rem; opacity: 0.55; }

    /* Sections */
    section { padding: 88px 0; }
    .section-head { text-align: center; max-width: 640px; margin: 0 auto 56px; }
    .section-head h2 { font-size: clamp(1.9rem, 4vw, 2.75rem); letter-spacing: -0.025em; line-height: 1.15; margin-bottom: 14px; }
    .section-head p { color: var(--muted); font-size: 1.1rem; }

    /* Features */
    .features { display: grid; grid-template-columns: repeat(3, 1fr); gap: 20px; }
    .feature { background: var(--surface); border: 1px solid var(--border); border-radius: var(--radius); padding: 28px; }
    .feature-icon { width: 44px; height: 44px; border-radius: 12px; background: var(--accent-soft); display: grid; place-items: center; font-size: 1.3rem; margin-bottom: 18px; }
    .feature h3 { font-size: 1.1rem; margin-bottom: 8px; }
    .feature p { color: var(--muted); font-size: 0.95rem; }

    /* Split */
    .split { display: grid; grid-template-columns: 1fr 1fr; gap: 64px; align-items: center; }
    .split + .split { margin-top: 96px; }
    .split.reverse .split-text { order: 2; }
    .split-text h3 { font-size: 2rem; letter-spacing: -0.02em; line-height: 1.2; margin-bottom: 16px; }
    .split-text p { color: var(--muted); font-size: 1.05rem; margin-bottom: 18px; }
    .checks { list-style: none; }
    .checks li { padding-left: 28px; position: relative; margin-bottom: 10px; }
    .checks li::before { content: "✓"; position: absolute; left: 0; color: var(--accent); font-weight: 700; }
    .split-visual {
      background: var(--surface); border: 1px solid var(--border); border-radius: 18px;
      padding: 28px; min-height: 280px; box-shadow: 0 16px 40px rgba(28, 27, 25, 0.06);
    }
    .search-box { border: 1px solid var(--border); border-radius: 10px; padding: 12px 14px; color: var(--muted); margin-bottom: 16px; }
    .search-box strong { color: var(--ink); }
    .result { padding: 12px 14px; border-radius: 10px; margin-bottom: 8px; border: 1px solid var(--border); }
    .result small { display: block; color: var(--muted); }
    .result mark { background: #fff3bf; padding: 0 2px; border-radius: 3px; }
    .graph { position: relative; height: 240px; }
    .node { position: absolute; padding: 6px 12px; border-radius: 999px; background: var(--accent-soft); color: var(--accent); font-size: 0.85rem; font-weight: 600; }
    .node.main { background: var(--accent); color: #fff; }

    /* Testimonials */
    .quotes { display: grid; grid-template-columns: repeat(3, 1fr); gap: 20px; }
    .quote { background: var(--surface); border: 1px solid var(--border); border-radius: var(--radius); padding: 28px; }
    .quote p { margin-bottom: 20px; }
    .quote-author { display: flex; align-items: center; gap: 12px; font-size: 0.9rem; }
    .avatar { width: 38px; height: 38px; border-radius: 50%; background: var(--accent-soft); display: grid; place-items: center; font-weight: 700; color: var(--accent); }
    .quote-author small { display: block; color: var(--muted); }

    /* Pricing */
    .pricing { display: grid; grid-template-columns: repeat(3, 1fr); gap: 20px; align-items: stretch; }
    .plan { background: var(--surface); border: 1px solid var(--border); border-radius: 18px; padding: 32px; display: flex; flex-direction: column; }
    .plan.featured { border: 2px solid var(--accent); position: relative; }
    .plan.featured::before {
      content: "Most popular"; position: absolute; top: -13px; left: 32px;
      background: var(--accent); color: #fff; font-size: 0.75rem; font-weight: 700;
