    .phone-screen small { color: var(--muted); display: block; margin-bottom: 16px; }
    .log-item { border: 1px solid var(--line); border-radius: 8px; padding: 10px 12px; margin-bottom: 10px; font-size: .82rem; }
    .log-item b { display: block; color: var(--charcoal); }
    .log-item span { color: var(--muted); }

    /* Steps */
    .steps { display: grid; grid-template-columns: repeat(3, 1fr); gap: 32px; counter-reset: step; }
    .step { text-align: center; padding: 0 12px; }
    .step::before {
      counter-increment: step;
      content: counter(step);
      display: grid; place-items: center;
      width: 56px; height: 56px; margin: 0 auto 18px;
      border-radius: 50%;
      background: var(--charcoal); color: var(--orange);
      font-weight: 800; font-size: 1.3rem;
    }
    .step h3 { margin-bottom: 8px; color: var(--charcoal); }
    .step p { color: var(--muted); }

    /* Stats */
    .stats { background: var(--charcoal); color: var(--white); padding: 72px 0; }
    .stats .container { display: grid; grid-template-columns: repeat(4, 1fr); gap: 24px; text-align: center; }
    .stat b { display: block; font-size: 2.6rem; color: var(--orange); letter-spacing: -1px; }
    .stat span { color: #C9CDD2; font-size: .95rem; }

    /* Testimonials */
    .testimonials { display: grid; grid-template-columns: repeat(3, 1fr); gap: 24px; }
    .quote {
      border: 1px solid var(--line);
      border-radius: var(--radius);
      padding: 30px;
      display: flex; flex-direction: column; justify-content: space-between;
    }
    .quote p { font-size: 1.02rem; margin-bottom: 22px; }
    .quote-author b { display: block; color: var(--charcoal); }
    .quote-author span { color: var(--muted); font-size: .9rem; }

    /* Pricing */
    .pricing { background: var(--concrete); }
    .plans { display: grid; grid-template-columns: repeat(3, 1fr); gap: 24px; align-items: stretch; }
    .plan {
      background: var(--white);
      border: 1px solid var(--line);
      border-radius: var(--radius);
      padding: 36px 30px;
      display: flex; flex-direction: column;
    }
    .plan.featured { border: 2px solid var(--orange); position: relative; }
    .plan.featured::before {
      content: "Most popular";
      position: absolute; top: -13px; left: 50%; transform: translateX(-50%);
      background: var(--orange); color: var(--white);
      font-size: .75rem; font-weight: 700; padding: 4px 12px; border-radius: 999px;
    }
    .plan h3 { color: var(--charcoal); margin-bottom: 6px; }
    .plan .desc { color: var(--muted); font-size: .93rem; margin-bottom: 20px; }
    .price { font-size: 2.4rem; font-weight: 800; color: var(--charcoal); letter-spacing: -1px; }
    .price small { font-size: .95rem; font-weight: 500; color: var(--muted); letter-spacing: 0; }
    .plan ul { list-style: none; margin: 24px 0 30px; flex: 1; }
    .plan li { padding: 8px 0; border-bottom: 1px solid var(--line); font-size: .95rem; }
    .plan li:last-child { border-bottom: none; }
    .plan .btn { text-align: center; }
    .btn-outline { border: 2px solid var(--charcoal); color: var(--charcoal); }
    .btn-outline:hover { background: var(--charcoal); color: var(--white); }

    /* FAQ */
    .faq { max-width: 780px; margin: 0 auto; }
    details { border-bottom: 1px solid var(--line); padding: 22px 0; }
    summary { font-weight: 600; font-size: 1.08rem; cursor: pointer; color: var(--charcoal); list-style: none; display: flex; justify-content: space-between; }
    summary::after { content: "+"; color: var(--orange); font-size: 1.4rem; line-height: 1; }
    details[open] summary::after { content: "−"; }
    details p { color: var(--muted); margin-top: 12px; }

    /* Final CTA */
    .final-cta {
      background: var(--orange);
      color: var(--white);
      text-align: center;
      padding: 88px 0;
    }
    .final-cta h2 { font-size: 2.5rem; letter-spacing: -1px; margin-bottom: 14px; }
    .final-cta p { font-size: 1.15rem; margin-bottom: 32px; opacity: .92; }
    .final-cta .btn-primary { background: var(--charcoal); }
    .final-cta .btn-primary:hover { background: #000; }

    /* Footer */
    footer { background: var(--charcoal); color: #9AA1A8; padding: 56px 0 32px; font-size: .92rem; }
    .footer-grid { display: grid; grid-template-columns: 2fr 1fr 1fr 1fr; gap: 32px; margin-bottom: 40px; }
    footer h5 { color: var(--white); font-size: .95rem; margin-bottom: 14px; }
    footer ul { list-style: none; }
    footer li { margin-bottom: 8px; }
    footer a:hover { color: var(--white); }
    .footer-bottom { border-top: 1px solid var(--steel); padding-top: 24px; display: flex; justify-content: space-between; flex-wrap: wrap; gap: 12px; }

    /* Responsive */
